#include <vector>
#include <unordered_set>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    long long minArraySum(std::vector<int>& nums) {
        std::unordered_set<int> numSet(nums.begin(), nums.end());
        if (numSet.count(1)) return nums.size();
        std::unordered_map<int, int> minDiv;
        for (int v : numSet) {
            int best = v;
            for (int d = 1; (long long)d * d <= v; ++d) {
                if (v % d == 0) {
                    if (numSet.count(d)) best = std::min(best, d);
                    if (numSet.count(v / d)) best = std::min(best, v / d);
                }
            }
            minDiv[v] = best;
        }
        long long ans = 0;
        for (int x : nums) ans += minDiv[x];
        return ans;
    }
};

import java.util.*;

class Solution {
    public long minArraySum(int[] nums) {
        Set<Integer> numSet = new HashSet<>();
        for (int x : nums) numSet.add(x);
        if (numSet.contains(1)) return nums.length;
        Map<Integer, Integer> minDiv = new HashMap<>();
        for (int v : numSet) {
            int best = v;
            for (int d = 1; (long)d * d <= v; d++) {
                if (v % d == 0) {
                    if (numSet.contains(d)) best = Math.min(best, d);
                    if (numSet.contains(v / d)) best = Math.min(best, v / d);
                }
            }
            minDiv.put(v, best);
        }
        long ans = 0;
        for (int x : nums) ans += minDiv.get(x);
        return ans;
    }
}

